import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a skewed quadratic bowl with sinusoidal modulation and pairwise interactions,
    designed to approximate the target ELA features. Uses a Gaussian mixture to create skewed distribution.

    Formula:
    f(x) = quadratic_bowl(x) + sinusoidal_modulation(x) + interaction_term(x) + gaussian_mixture(x)

    Components:
    - quadratic_bowl: Basic quadratic bowl with varying coefficients to simulate curvature
    - sinusoidal_modulation: Sinusoidal terms introduce oscillations and modality.  Uses different frequencies and amplitudes to shape the landscape.
    - interaction_term: Introduces pairwise variable interactions to change linear dependencies.
    - gaussian_mixture: Mixture of Gaussian distributions to introduce skew in the fitness distribution.
    """
    def quadratic_bowl(x):
        return np.sum(np.array([1.0, 0.5, 0.25]) * x**2)

    def sinusoidal_modulation(x):
        frequencies = np.array([2.0, 3.0, 1.0])
        amplitudes = np.array([0.5, 0.3, 0.2])
        return np.sum(amplitudes * np.sin(frequencies * x))

    def interaction_term(x):
         return 0.1 * (x[0]*x[1] + x[1]*x[2]) # Pairwise product of first two dims

    def gaussian_mixture(x, locs=[(-1, 0, 1)], scales=[(0.5, 0.5, 0.5)], weights=[0.2, 0.3, 0.5]):
        """Adds a Gaussian mixture to the landscape, affecting skewness"""
        densities = []
        for loc, scale, weight in zip(locs, scales, weights):
            density = weight * np.exp(-0.5 * np.sum(((x - np.array(loc)) / np.array(scale))**2))
            densities.append(density)
        return np.sum(densities)

    return quadratic_bowl(x) + sinusoidal_modulation(x) + interaction_term(x) + gaussian_mixture(x)
